const email = $json;
const knownApps = $('Get_Known_Applications').all().map(i => ({ application_id: i.json.id, company: i.json.fields?.company, title: i.json.fields?.title, application_date: i.json.fields?.application_date }));

const systemPrompt = `Tu es EMAIL_RESPONSE_MONITOR. Classifie EXACTEMENT en une catégorie: APPLICATION_CONFIRMATION, RECRUITER_MESSAGE, INTERVIEW_REQUEST, TECHNICAL_TEST, REJECTION, JOB_OFFER, REQUEST_FOR_INFORMATION, UNKNOWN. Extrais company, job_title, recruiter_name, action_required, deadline, proposed_date. Fais correspondre à known_applications SEULEMENT si raisonnablement certain (sinon matched_application_id=null). Ne rédige jamais de réponse au recruteur. Réponds UNIQUEMENT via l'outil return_email_classification.`;
const userMessage = JSON.stringify({
  email_subject: email.subject,
  email_body: (email.bodyPreview || (email.body && email.body.content) || '').toString().slice(0, 6000),
  email_from: (email.from && email.from.emailAddress && email.from.emailAddress.address) || '',
  email_date: email.receivedDateTime,
  known_applications: knownApps
});

return [{ json: { ...email, em_system_prompt: systemPrompt, em_user_message: userMessage } }];

return $input.all().map(item => {
  const body = item.json;
  const toolUse = (body.content || []).find(c => c.type === 'tool_use');
  const classification = toolUse ? toolUse.input : {};
  const email = $('Build_Email_Monitor_Request').first().json;
  return { json: { ...email, email_classification: { ...classification, model: body.model } } };
});

return $input.all().map(item => {
  const body = item.json;
  const email = $('Build_Email_Monitor_Request').first().json;
  let classification = {};
  try { classification = JSON.parse(body.choices[0].message.content); } catch (e) { classification = { classification: 'UNKNOWN', confidence: 'UNKNOWN', extracted: {}, matched_application_id: null, suggested_application_status: null }; }
  return { json: { ...email, email_classification: { ...classification, model: 'openai-fallback' } } };
});
